def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the uniform divider.
    for r in range(h):
        if len(set(grid[r])) == 1:
            left = grid[:r]
            right = grid[r + 1:]
            break
    else:
        c = next(j for j in range(w)
                 if all(grid[i][j] == grid[0][j] for i in range(h)))
        left = [row[:c] for row in grid]
        right = [row[c + 1:] for row in grid]

    # Recode the right-hand pattern using the two colors from the left.
    from collections import Counter
    counts = Counter(x for row in right for x in row)
    colors = [x for x, _ in counts.most_common()]
    if len(colors) < 2:
        return right

    # Most common right color becomes the left panel's first color;
    # the other becomes its second color.
    left_counts = Counter(x for row in left for x in row)
    left_colors = [x for x, _ in left_counts.most_common()]
    if len(left_colors) < 2:
        left_colors = left_colors * 2
    mapping = {colors[0]: left_colors[0], colors[1]: left_colors[1]}
    return [[mapping.get(x, left_colors[0]) for x in row] for row in right]
