def transform(grid):
    h, w = len(grid), len(grid[0])

    # Split along the solid divider. The output is the panel before the
    # divider, with its color shared by both panels preserved and the
    # other color changed to 3.
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            left_colors = {x for row in left for x in row}
            right_colors = {x for row in right for x in row}
            shared = left_colors & right_colors
            keep = next(iter(shared))
            return [[x if x == keep else 3 for x in row] for row in left]

    for r in range(h):
        if len(set(grid[r])) == 1:
            above = grid[:r]
            below = grid[r + 1:]
            shared = ({x for row in above for x in row} &
                      {x for row in below for x in row})
            keep = next(iter(shared))
            return [[x if x == keep else 3 for x in row] for row in above]

    return grid
